def split_rent(total, roommates):
    if total < 0:
        raise ValueError("total must not be negative")
    if roommates <= 0:
        raise ValueError("roommates must be greater than 0")
    cents = round(total * 100)
    base, extra = divmod(cents, roommates)
    return [(base + (1 if i < extra else 0)) / 100 for i in range(roommates)]
```

